INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_ARMENIAN_CHR','Armenian Christian period',300,1100)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_AGATHANGELOS_HISTORY','primary text','Agathangelos, History of the Armenians (Patmut''iwn Hayots''), 5th c. CE; trans. Robert W. Thomson (SUNY Press, Albany, 1976)','Reused: the standard 5th-c. account of the conversion of Armenia under King Tiridates III and Gregory the Illuminator; primary attestation for Gregory, Tiridates, and the founding of the Armenian Apostolic Church.'),
 ('SRC_KHORENATSI_HISTORY','primary text','Movses Khorenatsi, History of Armenia (Patmut''iwn Hayots''), 5th c. CE; trans. Robert W. Thomson (Harvard University Press, Cambridge MA, 1978)','Reused: 5th-c. Armenian national history written within the circle of Mashtots and Sahak; primary attestation for Mesrop Mashtots''s invention of the alphabet, Sahak Partev, and Nerses the Great.'),
 ('SRC_RUSSELL_ZOR_ARMENIA','secondary scholarship','James R. Russell, Zoroastrianism in Armenia (Harvard Iranian Series 5, 1987)','Reused here for the pre-Christian-to-Christian transition: documents the replacement of the Iranian/Zoroastrian yazata cult (Aramazd etc.) by the Christianity established under Tiridates and Gregory the Illuminator.'),
 ('SRC_NAREK_LAMENTATIONS','primary text','Gregory of Narek, The Book of Lamentations (Matean Voghbergut''ean / Narek), c. 1002-1003 CE; trans. Thomas J. Samuelian, Speaking with God from the Depths of the Heart (Vem Press, Yerevan, 2002)','The masterwork of Armenian Christian mysticism: 95 prayer-poems of penitential dialogue with God. Primary attestation for Gregory of Narek as mystic-poet of the Narek monastery (Vaspurakan), proclaimed a Doctor of the Universal Church in 2015.')
INSERT INTO _e VALUES
 ('ENT_ARMC_FATHERS','Fathers and Saints of the Armenian Apostolic Church','Saint collective','Collective','Armenian Christian','national church, sanctity, apostolic lineage','B','Collective hub for the founding and formative saints of the Armenian Apostolic Church; a modeling hub, not an attested single figure.'),
 ('ENT_ARMC_GREGORY_ILLUMINATOR','Gregory the Illuminator','Bishop/saint','Founder/saint','Armenian Christian','evangelization, episcopate, apostolic foundation','B','Saint Gregory the Illuminator (c.257-c.331), apostle and first Catholicos of Armenia; converted King Tiridates III and Christianized Armenia c.301. Attested in Agathangelos''s History as the chief agent of the conversion. A venerated human, not deified.'),
 ('ENT_ARMC_TIRIDATES','Tiridates III of Armenia','Royal saint','Royal saint','Armenian Christian','kingship, royal conversion, patronage','B','King Trdat (Tiridates) III (r. c.287-330), the Arsacid monarch converted by Gregory the Illuminator who made Christianity the state religion of Armenia c.301; venerated as a saint. Attested in Agathangelos. A venerated human ruler, not deified.'),
 ('ENT_ARMC_MESROP','Mesrop Mashtots','Monk/saint','Founder/saint','Armenian Christian','alphabet, scripture translation, monasticism','B','Saint Mesrop Mashtots (c.362-440), inventor of the Armenian alphabet (c.405) and translator of scripture, working under Catholicos Sahak. Attested in Movses Khorenatsi (Book III). A venerated human, not deified.'),
 ('ENT_ARMC_SAHAK','Sahak Partev','Bishop/saint','Bishop/saint','Armenian Christian','catholicate, scripture translation, ecclesial reform','B','Saint Sahak Partev (Isaac of Armenia, c.354-439), Catholicos of All Armenians and descendant of Gregory the Illuminator; co-sponsored the Mashtots alphabet and the Armenian Bible translation. Attested in Movses Khorenatsi. A venerated human, not deified. (Distinct homonym from Yarsan ENT_YRS_SULTAN_SAHAK.)'),
 ('ENT_ARMC_NERSES','Nerses the Great','Bishop/saint','Bishop/saint','Armenian Christian','catholicate, ecclesial reform, charity','B','Saint Nerses I the Great (Catholicos c.353-373), great-grandson of Gregory the Illuminator and reforming Catholicos who convened the Council of Ashtishat and founded hospitals and almshouses. Attested in Movses Khorenatsi and Faustus of Byzantium. A venerated human, not deified.'),
 ('ENT_ARMC_NAREK','Gregory of Narek','Mystic/saint','Mystic/saint','Armenian Christian','mysticism, sacred poetry, penitential prayer','B','Saint Gregory of Narek (c.945-1003), monk of Narekavank and Armenia''s greatest mystical poet; author of the Book of Lamentations, declared a Doctor of the Universal Church by Pope Francis in 2015. Attested through his surviving works. A venerated human, not deified. (Distinct from existing ENT_ORTH_GREGORY_THEOLOGIAN and ENT_ORTH_PALAMAS.)');
