INSERT INTO _p VALUES
 ('ENT_ARMC_FATHERS','PER_ARMENIAN_CHR','Collective hub for the founding and formative saints of the Armenian Apostolic Church; a modeling hub, not an attested single figure.'),
 ('ENT_ARMC_GREGORY_ILLUMINATOR','PER_ARMENIAN_CHR','Saint Gregory the Illuminator (c.257-c.331), apostle and first Catholicos of Armenia; converted King Tiridates III and Christianized Armenia c.301. Attested in Agathangelos''s History as the chief agent of the conversion. A venerated human, not deified.'),
 ('ENT_ARMC_TIRIDATES','PER_ARMENIAN_CHR','King Trdat (Tiridates) III (r. c.287-330), the Arsacid monarch converted by Gregory the Illuminator who made Christianity the state religion of Armenia c.301; venerated as a saint. Attested in Agathangelos. A venerated human ruler, not deified.'),
 ('ENT_ARMC_MESROP','PER_ARMENIAN_CHR','Saint Mesrop Mashtots (c.362-440), inventor of the Armenian alphabet (c.405) and translator of scripture, working under Catholicos Sahak. Attested in Movses Khorenatsi (Book III). A venerated human, not deified.'),
 ('ENT_ARMC_SAHAK','PER_ARMENIAN_CHR','Saint Sahak Partev (Isaac of Armenia, c.354-439), Catholicos of All Armenians and descendant of Gregory the Illuminator; co-sponsored the Mashtots alphabet and the Armenian Bible translation. Attested in Movses Khorenatsi. A venerated human, not deified. (Distinct homonym from Yarsan ENT_YRS_SULTAN_SAHAK.)'),
 ('ENT_ARMC_NERSES','PER_ARMENIAN_CHR','Saint Nerses I the Great (Catholicos c.353-373), great-grandson of Gregory the Illuminator and reforming Catholicos who convened the Council of Ashtishat and founded hospitals and almshouses. Attested in Movses Khorenatsi and Faustus of Byzantium. A venerated human, not deified.'),
 ('ENT_ARMC_NAREK','PER_ARMENIAN_CHR','Saint Gregory of Narek (c.945-1003), monk of Narekavank and Armenia''s greatest mystical poet; author of the Book of Lamentations, declared a Doctor of the Universal Church by Pope Francis in 2015. Attested through his surviving works. A venerated human, not deified. (Distinct from existing ENT_ORTH_GREGORY_THEOLOGIAN and ENT_ORTH_PALAMAS.)');
