INSERT INTO _r VALUES
 ('ENT_ARMC_GREGORY_ILLUMINATOR','member_of','ENT_ARMC_FATHERS','high','Gregory the Illuminator is the founding father and first Catholicos of the Armenian Apostolic Church (Agathangelos).'),
 ('ENT_ARMC_TIRIDATES','member_of','ENT_ARMC_FATHERS','high','King Tiridates III is venerated as a saint of the Armenian Church for establishing it as the state religion.'),
 ('ENT_ARMC_MESROP','member_of','ENT_ARMC_FATHERS','high','Mesrop Mashtots is among the formative saints (Holy Translators) of the Armenian Apostolic Church.'),
 ('ENT_ARMC_SAHAK','member_of','ENT_ARMC_FATHERS','high','Sahak Partev, Catholicos, is among the founding saints (Holy Translators) of the Armenian Church.'),
 ('ENT_ARMC_NERSES','member_of','ENT_ARMC_FATHERS','high','Nerses the Great, reforming Catholicos, is a venerated father of the Armenian Church.'),
 ('ENT_ARMC_NAREK','member_of','ENT_ARMC_FATHERS','high','Gregory of Narek, mystic-poet and Doctor of the Church, is among the great saints of the Armenian Church.'),
 ('ENT_ARMC_TIRIDATES','taught_by','ENT_ARMC_GREGORY_ILLUMINATOR','high','Agathangelos records that Gregory the Illuminator converted and catechized King Tiridates III into the Christian faith.'),
 ('ENT_ARMC_MESROP','taught_by','ENT_ARMC_SAHAK','high','Movses Khorenatsi records Mesrop Mashtots working under and with Catholicos Sahak Partev, who sponsored the alphabet and Bible translation.'),
 ('ENT_ARMC_SAHAK','child_of','ENT_ARMC_NERSES','medium','Sahak Partev was the son of Nerses the Great (Faustus/Khorenatsi genealogy of the line of Gregory the Illuminator).'),
 ('ENT_ARMC_GREGORY_ILLUMINATOR','opposes','ENT_ARM_ARAMAZD','high','Agathangelos records Gregory the Illuminator''s destruction of the cult of Aramazd and the other pre-Christian Armenian deities during the conversion.'),
 ('ENT_ARMC_TIRIDATES','opposes','ENT_ARM_ANAHIT','medium','After his conversion, Tiridates III ordered the destruction of the temples of Anahit and the other Armenian deities (Agathangelos).'),
 ('ENT_ARMC_NAREK','reception_of','ENT_SAINT_MARY','medium','Gregory of Narek composed major Marian panegyrics venerating the Theotokos; re-pointed to the existing Mary Theotokos entity (ENT_SAINT_MARY, Mary mother of Jesus) after QA found the proposed object ENT_NT_MARY_OF_JAMES was the wrong Mary and the homonym claim false.');
